import { preloadCompactJsonSchema } from "../utils/compact-json-schema.js";
import {
	getRegisteredToolConfig,
	registerToolDefinition,
	type ToolRegistrar,
} from "./define-tool.js";
import { bodyMeasurementToolDefinitions } from "./body-measurements.js";
import { folderToolDefinitions } from "./folders.js";
import { routineToolDefinitions } from "./routines.js";
import { templateToolDefinitions } from "./templates.js";
import { routineDiscoveryToolDefinitions } from "./routine-discovery.js";
import { workflowToolDefinitions } from "./workflows.js";
import { workoutToolDefinitions } from "./workouts.js";
import type { ToolRuntime } from "./tool-runtime.js";

export const hevyToolDefinitions = [
	...workoutToolDefinitions,
	...routineToolDefinitions,
	...templateToolDefinitions,
	...folderToolDefinitions,
	...bodyMeasurementToolDefinitions,
	...workflowToolDefinitions,
	...routineDiscoveryToolDefinitions,
] as const;

/**
 * Move the one-time tool schema conversion into module scope.
 *
 * Tool schemas are module-level constants, and their compact JSON Schema is
 * memoized per definition by `getRegisteredToolConfig`. Populating the memo is
 * not enough: `compactJsonSchema` stores the actual `z.toJSONSchema` work
 * behind lazy `input`/`output` closures, and the MCP SDK invokes those during
 * `registerTool`. This forces the exact conversions the SDK consumes (`input`
 * for each `inputSchema`, `output` for each read tool `outputSchema`) so a
 * first request only reads already-converted schemas.
 *
 * On isolate-based edge runtimes (Cloudflare Workers) module-scope work runs
 * during isolate warm-up, outside a request's billed CPU, so calling this at
 * module scope keeps the first request of a fresh isolate fast. Idempotent,
 * and a no-op after every conversion has been computed once.
 */
export function preloadHevyToolSchemas(): void {
	for (const definition of hevyToolDefinitions) {
		const config = getRegisteredToolConfig(definition);
		preloadCompactJsonSchema(config.inputSchema, "input");
		if (config.outputSchema) {
			preloadCompactJsonSchema(config.outputSchema, "output");
		}
	}
}

/** Register every Hevy tool in its production ordering. */
export function registerHevyTools(
	server: ToolRegistrar,
	runtime: ToolRuntime,
): void {
	for (const definition of hevyToolDefinitions) {
		registerToolDefinition(server, runtime, definition);
	}
}

import { Context, Effect, Layer, Scope } from "effect";
import type { McpClientLogger } from "../utils/mcp-client-logger.js";
import type { HevyClient } from "@hevy-mcp/hevy-client";
import { createOperations, type HevyOperations } from "@hevy-mcp/operations";
import {
	createCoreServiceLayer,
	createToolObserverLayer,
	type CoreServiceIdentifiers,
} from "../effect-layer.js";
import {
	HevyClientService,
	HevyOperationsService,
	ToolObserverService,
} from "../effect-services.js";
import {
	HEVY_CLIENT_NOT_INITIALIZED_ERROR,
	requireClient,
} from "../utils/tool-helpers.js";
import { withErrorHandling } from "../utils/error-handler.js";
import type { ExerciseTemplateCatalog } from "../utils/exercise-template-catalog.js";
import type { McpToolResponse } from "../utils/response-contracts.js";
import type { ToolTelemetryMetadata } from "../utils/tool-taxonomy.js";
import {
	memoizeObservationScope,
	type SafeToolArgumentKey,
	type ToolObserver,
	type ToolCompletionObservation,
} from "../observation.js";
import { bucketCount, getResultTelemetry } from "../utils/result-telemetry.js";
import { resolveErrorPolicy } from "../utils/error-policy.js";
import {
	bindClientExecution,
	mergeAbortSignals,
	type ToolExecutionContext,
} from "../execution.js";
import { DEFAULT_API_TIMEOUT_MS } from "@hevy-mcp/hevy-client";
import { TELEMETRY_ARGUMENT_KEYS } from "../utils/telemetry-contract.js";
import { isBoolean, isFiniteNumber } from "../utils/type-predicates.js";

interface ArgumentKeySet {
	readonly [key: string]: true;
}

const toKeySet = (keys: readonly string[]): Readonly<ArgumentKeySet> =>
	Object.fromEntries(keys.map((key) => [key, true as const]));

const STRUCTURAL_ARGUMENT_KEYS: Readonly<ArgumentKeySet> = toKeySet(
	TELEMETRY_ARGUMENT_KEYS,
);

const PRESENCE_ARGUMENT_KEYS: Readonly<ArgumentKeySet> = {
	since: true,
	workout_id: true,
	routine_id: true,
	folder_id: true,
	exercise_template_id: true,
	date: true,
	start_date: true,
	end_date: true,
	updated_since: true,
	query: true,
	primary_muscle_group: true,
};

const NUMERIC_ARGUMENT_KEYS: Readonly<ArgumentKeySet> = {
	page: true,
	page_size: true,
	limit: true,
	offset: true,
};

const BOOLEAN_ARGUMENT_KEYS: Readonly<ArgumentKeySet> = {
	include_custom: true,
	refresh: true,
};

const structuralArgumentKeys = Object.keys(
	STRUCTURAL_ARGUMENT_KEYS,
) as SafeToolArgumentKey[];

type ToolRuntimeServiceIdentifiers =
	| CoreServiceIdentifiers
	| ToolObserverService;
type ToolRuntimeServiceLayer = Layer.Layer<ToolRuntimeServiceIdentifiers>;
type ToolRuntimeServiceContext = Context.Context<ToolRuntimeServiceIdentifiers>;

function buildServiceContext(
	layer: ToolRuntimeServiceLayer,
): ToolRuntimeServiceContext {
	// Build the layer against a scope that outlives this call. `Effect.scoped`
	// would close the scope immediately, releasing any scoped resources
	// before the returned context is ever used by request handlers.
	const scope = Effect.runSync(Scope.make());
	return Effect.runSync(Scope.provide(scope)(Layer.build(layer)));
}

function createSafeInvocation<TArgs extends object>(
	name: string,
	args: TArgs,
	taxonomy: ToolTelemetryMetadata | undefined,
) {
	const argumentValues = new Map<string, unknown>(Object.entries(args));
	const argumentKeys = structuralArgumentKeys.filter((key) => key in args);
	const argumentPresence: Record<string, true> = {};
	const numericArgumentBuckets: Record<
		string,
		ReturnType<typeof bucketCount>
	> = {};
	const booleanArguments: Record<string, boolean> = {};

	for (const key of argumentKeys) {
		const value = argumentValues.get(key);
		if (
			key in PRESENCE_ARGUMENT_KEYS &&
			value !== null &&
			value !== undefined
		) {
			argumentPresence[key] = true;
		}
		if (key in NUMERIC_ARGUMENT_KEYS && isFiniteNumber(value)) {
			numericArgumentBuckets[key] = bucketCount(value);
		}
		if (key in BOOLEAN_ARGUMENT_KEYS && isBoolean(value)) {
			booleanArguments[key] = value;
		}
	}

	return {
		name,
		taxonomy,
		argumentKeys,
		argumentPresence,
		numericArgumentBuckets,
		booleanArguments,
		argumentKeyCountBucket: bucketCount(Object.keys(args).length),
	};
}

export type ToolHandler<TParams extends object = object> = (
	args: TParams,
	context?: ToolExecutionContext,
) => Promise<McpToolResponse>;

export type ToolHandlerFactory = <TParams extends object>(
	fn: ToolHandler<TParams>,
	context: string,
	metadata?: ToolTelemetryMetadata,
) => ToolHandler;
export interface ToolRuntime {
	readonly client: HevyClient | null;
	readonly catalog: ExerciseTemplateCatalog;
	/** The request-local dependency graph used by Effect-backed tool code. */
	readonly layer?: ToolRuntimeServiceLayer;
	/** The context built from `layer`, kept request-local with the runtime. */
	readonly services?: ToolRuntimeServiceContext;
	readonly logger?: McpClientLogger;
	readonly execution?: ToolExecutionContext;
	readonly executionTimeoutMs: number;
	readonly executionDeadline?: number;
	readonly lifecycleSignal?: AbortSignal;
	readonly operations: HevyOperations | null;
	readonly createHandler: ToolHandlerFactory;
	service<I extends ToolRuntimeServiceIdentifiers, S>(
		service: Context.Key<I, S>,
	): S;
	getClient(): HevyClient;
	getOperations(): HevyOperations;
	forExecution(context?: ToolExecutionContext): ToolRuntime;
}

export interface CreateToolRuntimeOptions {
	client: HevyClient | null;
	/** Unbound client retained across nested execution scopes. */
	baseClient?: HevyClient | null;
	operations?: HevyOperations;
	catalog: ExerciseTemplateCatalog;
	logger?: McpClientLogger;
	createHandler?: ToolHandlerFactory;
	observer?: ToolObserver;
	execution?: ToolExecutionContext;
	executionTimeoutMs?: number;
	executionDeadline?: number;
	lifecycleSignal?: AbortSignal;
}

export const defaultHandlerFactory: ToolHandlerFactory = <
	TParams extends object,
>(
	fn: ToolHandler<TParams>,
	context: string,
) => withErrorHandling(fn, context) as ToolHandler;

export function createToolRuntime({
	client,
	baseClient,
	operations,
	catalog,
	logger,
	createHandler = defaultHandlerFactory,
	observer,
	execution,
	executionTimeoutMs = DEFAULT_API_TIMEOUT_MS,
	executionDeadline,
	lifecycleSignal,
}: CreateToolRuntimeOptions): ToolRuntime {
	const rawClient = baseClient ?? client;
	const resolvedOperations =
		operations ?? (rawClient ? createOperations(rawClient) : null);
	const effectiveExecutionDeadline = executionDeadline ?? execution?.deadline;
	const effectiveClient =
		execution && rawClient
			? bindClientExecution(requireClient(rawClient), execution)
			: client;
	const effectiveCatalog = execution
		? {
				get: (options = {}) => catalog.get({ ...options, execution }),
				reset: () => catalog.reset(),
			}
		: catalog;
	const coreLayer =
		effectiveClient && resolvedOperations
			? (createCoreServiceLayer({
					client: effectiveClient,
					catalog: effectiveCatalog,
					execution: execution ?? {},
					operations: resolvedOperations,
				}) as ToolRuntimeServiceLayer)
			: resolvedOperations
				? (Layer.succeed(
						HevyOperationsService,
						resolvedOperations,
					) as ToolRuntimeServiceLayer)
				: undefined;
	const layer = observer
		? coreLayer
			? (Layer.merge(
					coreLayer,
					createToolObserverLayer(observer),
				) as ToolRuntimeServiceLayer)
			: (createToolObserverLayer(observer) as ToolRuntimeServiceLayer)
		: coreLayer;
	const services = layer ? buildServiceContext(layer) : undefined;
	const getService = <I extends ToolRuntimeServiceIdentifiers, S>(
		service: Context.Key<I, S>,
	): S => {
		if (service.key === HevyClientService.key) {
			requireClient(effectiveClient);
		}
		if (!services) {
			throw new Error("Core service layer is unavailable");
		}
		return Context.get(services, service);
	};
	const createObservedHandler: ToolHandlerFactory = <TParams extends object>(
		fn: ToolHandler<TParams>,
		context: string,
		metadata?: ToolTelemetryMetadata,
	) =>
		createHandler<TParams>(
			async (args: TParams, requestContext?: ToolExecutionContext) => {
				let scope;
				try {
					scope = memoizeObservationScope(
						observer?.start(createSafeInvocation(context, args, metadata)),
					);
				} catch {
					scope = undefined;
				}
				const startedAt = Date.now();
				let handlerPromise: Promise<McpToolResponse> | undefined;
				const invokeHandler = () => {
					handlerPromise ??= Promise.resolve().then(() =>
						fn(args, requestContext),
					);
					return handlerPromise;
				};
				try {
					let runPromise: Promise<McpToolResponse>;
					if (scope) {
						try {
							runPromise = scope.run(invokeHandler);
						} catch {
							runPromise = invokeHandler();
						}
					} else {
						runPromise = invokeHandler();
					}
					const result = await runPromise.catch(invokeHandler);
					const telemetry = {
						outcome: result.isError ? "returned_error" : "success",
						durationMs: Date.now() - startedAt,
						errorOutcome: result.errorOutcome,
						result: {
							isError: Boolean(result.isError),
							hasStructuredContent: result.structuredContent !== undefined,
							contentCountBucket: bucketCount(result.content.length),
							summary: getResultTelemetry(result),
						},
					} satisfies ToolCompletionObservation;
					void scope?.finish(telemetry);
					return result;
				} catch (error) {
					const policy = resolveErrorPolicy(error, "");
					void scope?.finish({
						outcome: "thrown_error",
						durationMs: Date.now() - startedAt,
						errorType: policy.type,
						error: policy.diagnostic,
					});
					throw error;
				}
			},
			context,
			metadata,
		);
	const observedHandlerFactory = observer
		? createObservedHandler
		: createHandler;
	const runtime: ToolRuntime = {
		client: effectiveClient,
		catalog: effectiveCatalog,
		layer,
		services,
		logger,
		execution,
		executionTimeoutMs,
		executionDeadline: effectiveExecutionDeadline,
		lifecycleSignal,
		operations: resolvedOperations,
		createHandler: observedHandlerFactory,
		service: getService,
		getClient: () =>
			effectiveClient && services
				? getService(HevyClientService)
				: requireClient(effectiveClient),
		getOperations: () =>
			resolvedOperations && services
				? getService(HevyOperationsService)
				: (resolvedOperations ??
					createOperations(requireClient(effectiveClient))),
		forExecution: (nextExecution) =>
			createToolRuntime({
				client: rawClient,
				baseClient: rawClient,
				operations: resolvedOperations ?? undefined,
				catalog,
				logger,
				createHandler,
				observer,
				execution: (() => {
					const nested: {
						-readonly [
							K in keyof ToolExecutionContext
						]?: ToolExecutionContext[K];
					} = {};
					if (nextExecution) Object.assign(nested, nextExecution);
					nested.signal = mergeAbortSignals(
						lifecycleSignal,
						nextExecution?.signal,
					);
					nested.deadline =
						nextExecution?.deadline ??
						effectiveExecutionDeadline ??
						Date.now() + executionTimeoutMs;
					return nested as ToolExecutionContext;
				})(),
				executionTimeoutMs,
				executionDeadline:
					nextExecution?.deadline ?? effectiveExecutionDeadline,
				lifecycleSignal,
			}),
	};
	return runtime;
}

export { HEVY_CLIENT_NOT_INITIALIZED_ERROR };

import type {
	McpServer,
	ReadResourceResult,
	ServerContext,
} from "@modelcontextprotocol/server";
import type {
	GetV1WorkoutsCount200,
	RoutineFolder,
	UserInfoResponse,
} from "@hevy-mcp/hevy-client/types";
import type { ToolRuntime } from "../tools/tool-runtime.js";
import { fetchAllPages } from "../utils/pagination.js";
import { projectRoutineFolder } from "../utils/formatters.js";
import { createExecutionErrorProjection } from "../utils/error-handler.js";
import type { RuntimeValue } from "../utils/type-predicates.js";

const JSON_MIME_TYPE = "application/json";

function createJsonResourceResult(
	uri: URL,
	data: RuntimeValue,
): ReadResourceResult {
	return {
		contents: [
			{
				uri: uri.toString(),
				mimeType: JSON_MIME_TYPE,
				text: JSON.stringify(data),
			},
		],
	};
}

function createResourceErrorResult(
	uri: URL,
	error: RuntimeValue,
): ReadResourceResult {
	return createJsonResourceResult(uri, {
		error: createExecutionErrorProjection(error),
	});
}

async function readResource(
	uri: URL,
	read: () => Promise<ReadResourceResult>,
): Promise<ReadResourceResult> {
	try {
		return await read();
	} catch (error) {
		return createResourceErrorResult(uri, error);
	}
}

async function fetchAllRoutineFolders(
	runtime: ToolRuntime,
): Promise<RoutineFolder[]> {
	const client = runtime.getClient();
	return fetchAllPages<RoutineFolder>(async (page, pageSize) => {
		const data = await client.getRoutineFolders({ page, pageSize });
		return {
			items: data?.routine_folders ?? [],
			pageCount: data?.page_count,
		};
	}, 10);
}

export function registerHevyResources(
	server: McpServer,
	runtime: ToolRuntime,
): void {
	server.registerResource(
		"user-profile",
		"hevy://user",
		{
			description: "Authenticated Hevy user profile",
			mimeType: JSON_MIME_TYPE,
		},
		async (uri, context: ServerContext) =>
			readResource(uri, async () => {
				const scoped = runtime.forExecution({ signal: context.mcpReq.signal });
				const data: UserInfoResponse = await scoped.getClient().getUserInfo();
				return createJsonResourceResult(uri, data?.data ?? null);
			}),
	);

	server.registerResource(
		"workout-count",
		"hevy://workout-count",
		{
			description: "Total number of workouts in the Hevy account",
			mimeType: JSON_MIME_TYPE,
		},
		async (uri, context: ServerContext) =>
			readResource(uri, async () => {
				const scoped = runtime.forExecution({ signal: context.mcpReq.signal });
				const data: GetV1WorkoutsCount200 = await scoped
					.getClient()
					.getWorkoutCount();
				return createJsonResourceResult(uri, {
					workout_count: data?.workout_count ?? 0,
				});
			}),
	);

	server.registerResource(
		"exercise-templates",
		"hevy://exercise-templates",
		{
			description: "Full formatted Hevy exercise template catalog",
			mimeType: JSON_MIME_TYPE,
		},
		async (uri, context: ServerContext) =>
			readResource(uri, async () => {
				const scoped = runtime.forExecution({ signal: context.mcpReq.signal });
				const templates = await scoped.catalog.get();
				return createJsonResourceResult(uri, templates);
			}),
	);

	server.registerResource(
		"routine-folders",
		"hevy://routine-folders",
		{
			description: "Full formatted list of Hevy routine folders",
			mimeType: JSON_MIME_TYPE,
		},
		async (uri, context: ServerContext) =>
			readResource(uri, async () => {
				const folders = await fetchAllRoutineFolders(
					runtime.forExecution({ signal: context.mcpReq.signal }),
				);
				return createJsonResourceResult(uri, folders.map(projectRoutineFolder));
			}),
	);
}

import type { ResultCountBucket } from "./result-telemetry.js";
import type { RuntimeValue } from "./type-predicates.js";

export type CacheObservationState =
	| "hit"
	| "miss"
	| "refresh"
	| "expired"
	| "inflight_wait";

export interface CacheObservationMetadata {
	readonly refreshReason?: "explicit-refresh" | "initial-load" | "ttl-expired";
	readonly pageCountBucket?: ResultCountBucket;
	readonly itemCountBucket?: ResultCountBucket;
}

export interface CacheObservation extends CacheObservationMetadata {
	readonly state: CacheObservationState;
}

export interface CacheObservationScope {
	finish(metadata?: CacheObservationMetadata): void;
}

export interface CacheObserver {
	start(observation: CacheObservation): CacheObservationScope | void;
}

export interface AsyncCacheOptions {
	ttlMs: number;
	maxSize: number;
	observer?: CacheObserver;
}

export interface CacheGetOptions {
	refresh?: boolean;
	/** Controlled callers must not share an in-flight request they can cancel. */
	shareInFlight?: boolean;
	signal?: AbortSignal;
	deadline?: number;
	getObservationMetadata?: () => CacheObservationMetadata | undefined;
}

interface CacheEntry<TValue> {
	value: TValue;
	expiresAt: number;
}

interface InFlightEntry<TValue> {
	promise: Promise<TValue>;
	requestId: number;
}

/**
 * Shared in-memory cache for async fetches with TTL, LRU eviction,
 * in-flight de-duplication, and explicit refresh/invalidation support.
 */
export class AsyncTtlCache<TKey, TValue> {
	private readonly ttlMs: number;
	private readonly maxSize: number;
	private readonly now: () => number;
	private readonly observer?: CacheObserver;
	private readonly entries = new Map<TKey, CacheEntry<TValue>>();
	private readonly inFlight = new Map<TKey, InFlightEntry<TValue>>();
	/** Latest request generation per key, including unshared requests. */
	private readonly latestRequestIds = new Map<TKey, number>();
	private requestCounter = 0;

	constructor(options: AsyncCacheOptions, now: () => number = Date.now) {
		const { ttlMs, maxSize, observer } = options;
		if (ttlMs <= 0) {
			throw new Error("Cache ttlMs must be greater than 0.");
		}
		if (maxSize <= 0) {
			throw new Error("Cache maxSize must be greater than 0.");
		}

		this.ttlMs = ttlMs;
		this.maxSize = maxSize;
		this.now = now;
		this.observer = observer;
	}

	private startObservation(
		state: CacheObservationState,
	): CacheObservationScope | undefined {
		try {
			return this.observer?.start({ state }) ?? undefined;
		} catch {
			return undefined;
		}
	}

	private finishObservation(
		scope: CacheObservationScope | undefined,
		metadata?: CacheObservationMetadata,
	): void {
		try {
			scope?.finish(metadata);
		} catch {
			// Cache observation is best-effort and cannot affect cache behavior.
		}
	}

	private async waitForCaller<T>(
		promise: Promise<T>,
		signal?: AbortSignal,
		deadline?: number,
	): Promise<T> {
		if (signal === undefined && deadline === undefined) return promise;
		if (signal?.aborted) {
			throw (
				signal.reason ?? new DOMException("Operation canceled", "AbortError")
			);
		}
		if (deadline !== undefined && Date.now() >= deadline) {
			throw new DOMException("Operation deadline exceeded", "TimeoutError");
		}
		return new Promise<T>((resolve, reject) => {
			let settled = false;
			let timer: ReturnType<typeof setTimeout> | undefined;
			const cleanup = () => {
				if (timer !== undefined) clearTimeout(timer);
				signal?.removeEventListener("abort", onAbort);
			};
			const finish = (callback: () => void) => {
				if (settled) return;
				settled = true;
				cleanup();
				callback();
			};
			const onAbort = () =>
				finish(() =>
					reject(
						signal?.reason ??
							new DOMException("Operation canceled", "AbortError"),
					),
				);
			if (signal !== undefined)
				signal.addEventListener("abort", onAbort, { once: true });
			if (deadline !== undefined) {
				timer = setTimeout(
					() =>
						finish(() =>
							reject(
								new DOMException("Operation deadline exceeded", "TimeoutError"),
							),
						),
					Math.max(0, deadline - Date.now()),
				);
			}
			void promise.then(
				(value) => finish(() => resolve(value)),
				(error: RuntimeValue) => finish(() => reject(error)),
			);
		});
	}

	async getOrFetch(
		key: TKey,
		fetcher: () => Promise<TValue>,
		options: CacheGetOptions = {},
	): Promise<TValue> {
		const {
			refresh = false,
			shareInFlight = true,
			signal,
			deadline,
			getObservationMetadata,
		} = options;
		let observationState: CacheObservationState = refresh ? "refresh" : "miss";

		if (refresh) {
			if (shareInFlight) this.invalidate(key);
		} else {
			const cachedEntry = this.entries.get(key);
			if (cachedEntry !== undefined) {
				if (cachedEntry.expiresAt > this.now()) {
					this.markAsRecentlyUsed(key, cachedEntry);
					const observationScope = this.startObservation("hit");
					this.finishObservation(observationScope);
					return this.waitForCaller(
						Promise.resolve(cachedEntry.value),
						signal,
						deadline,
					);
				}

				this.entries.delete(key);
				observationState = "expired";
			}

			const inFlightEntry = shareInFlight ? this.inFlight.get(key) : undefined;
			if (inFlightEntry !== undefined) {
				const observationScope = this.startObservation("inflight_wait");
				void inFlightEntry.promise.then(
					() => this.finishObservation(observationScope),
					() => this.finishObservation(observationScope),
				);
				return this.waitForCaller(inFlightEntry.promise, signal, deadline);
			}
		}

		const requestId = ++this.requestCounter;
		this.latestRequestIds.set(key, requestId);
		const observationScope = this.startObservation(observationState);
		const request = (async () => {
			try {
				const value = await fetcher();

				if (this.isCurrentRequest(key, requestId)) {
					this.setValue(key, value);
				}

				return value;
			} finally {
				let metadata: CacheObservationMetadata | undefined;
				try {
					metadata = getObservationMetadata?.();
				} catch {
					metadata = undefined;
				}
				this.finishObservation(observationScope, metadata);
				const inFlightEntry = shareInFlight
					? this.inFlight.get(key)
					: undefined;
				if (inFlightEntry?.requestId === requestId) {
					this.inFlight.delete(key);
				}
				if (this.latestRequestIds.get(key) === requestId) {
					this.latestRequestIds.delete(key);
				}
			}
		})();

		if (shareInFlight) this.inFlight.set(key, { promise: request, requestId });
		return this.waitForCaller(request, signal, deadline);
	}

	invalidate(key: TKey): void {
		this.entries.delete(key);
		this.inFlight.delete(key);
		this.latestRequestIds.delete(key);
	}

	clear(): void {
		this.entries.clear();
		this.inFlight.clear();
		this.latestRequestIds.clear();
	}

	get size(): number {
		return this.entries.size;
	}

	private isCurrentRequest(key: TKey, requestId: number): boolean {
		return this.latestRequestIds.get(key) === requestId;
	}

	private markAsRecentlyUsed(key: TKey, entry: CacheEntry<TValue>): void {
		this.entries.delete(key);
		this.entries.set(key, entry);
	}

	private setValue(key: TKey, value: TValue): void {
		this.entries.delete(key);
		this.entries.set(key, {
			value,
			expiresAt: this.now() + this.ttlMs,
		});

		this.evictLeastRecentlyUsed();
	}

	private evictLeastRecentlyUsed(): void {
		while (this.entries.size > this.maxSize) {
			const oldestKey = this.entries.keys().next().value;
			if (oldestKey === undefined) {
				return;
			}

			this.entries.delete(oldestKey);
		}
	}
}

import { McpServer } from "@modelcontextprotocol/server";
import type { HevyClient, HevyClientLogEvent } from "@hevy-mcp/hevy-client";
import { registerWorkoutPrompts } from "./prompts/workouts.js";
import { registerHevyResources } from "./resources/hevy.js";
import {
	SERVER_INSTRUCTIONS,
	SERVER_NAME,
	SERVER_VERSION,
} from "./server-metadata.js";
import { registerHevyTools } from "./tools/register.js";
import { createToolRuntime } from "./tools/tool-runtime.js";
import { createExerciseTemplateCatalog } from "./utils/exercise-template-catalog.js";
import { createMcpClientLogger } from "./utils/mcp-client-logger.js";
import type { CacheObserver } from "./utils/cache.js";
import type { ToolObserver } from "./observation.js";
export interface HevyClientFactoryContext {
	readonly onLog: (event: HevyClientLogEvent) => void;
}

export interface CreateHevyMcpServerOptions {
	readonly createClient: (context: HevyClientFactoryContext) => HevyClient;
	readonly observer?: ToolObserver;
	readonly cacheObserver?: CacheObserver;
	readonly decorateServer?: (server: McpServer) => McpServer;
	readonly onToolsRegistered?: (count: number) => void;
	/** One absolute budget for each incoming MCP invocation. */
	readonly executionTimeoutMs?: number;
	/** Absolute deadline shared by validation and every tool call in one invocation. */
	readonly executionDeadline?: number;
	readonly lifecycleSignal?: AbortSignal;
}

function createCountingServer(server: McpServer) {
	let count = 0;
	const countingServer = new Proxy(server, {
		get(target, property, receiver) {
			if (property === "registerTool") {
				const registerTool = target.registerTool.bind(target);
				return (...args: unknown[]) => {
					const result = Reflect.apply(registerTool, target, args);
					count += 1;
					return result;
				};
			}
			return Reflect.get(target, property, receiver);
		},
	});
	return { server: countingServer, getCount: () => count };
}

export function createHevyMcpServer(
	options: CreateHevyMcpServerOptions,
): McpServer {
	const baseServer = new McpServer(
		{ name: SERVER_NAME, version: SERVER_VERSION },
		{ capabilities: { logging: {} }, instructions: SERVER_INSTRUCTIONS },
	);
	const server = options.decorateServer?.(baseServer) ?? baseServer;
	const mcpLogger = createMcpClientLogger(server);
	const client = options.createClient({ onLog: (event) => mcpLogger(event) });
	const runtime = createToolRuntime({
		client,
		catalog: createExerciseTemplateCatalog(client, options.cacheObserver),
		logger: mcpLogger,
		observer: options.observer,
		executionTimeoutMs: options.executionTimeoutMs,
		executionDeadline: options.executionDeadline,
		lifecycleSignal: options.lifecycleSignal,
	});
	const counting = createCountingServer(server);
	registerHevyTools(counting.server, runtime);
	options.onToolsRegistered?.(counting.getCount());
	registerWorkoutPrompts(server, options.observer);
	registerHevyResources(server, runtime);
	return server;
}

